from pathlib import Path
import pandas as pd,json
base=Path('dataset')
cal=json.loads((base/'sensors_calibration.json').read_text())['enterprise_platform']['deployment_environments']['system_config']['farms']

def load(fid):
 p=base/f'production_{fid}.csv'; raw=p.read_bytes(); enc='utf-16' if raw[:2] in (b'\xff\xfe',b'\xfe\xff') else 'utf-8-sig'; text=raw.decode(enc); h=text.splitlines()[3]; sep=';' if h.count(';')>h.count(',') else ','
 return pd.read_csv(p,encoding=enc,skiprows=3,sep=sep,dtype=str,keep_default_na=False),sep

def num(s,sep):
 s=str(s).strip()
 if sep==';' and ',' in s: s=s.replace('.','').replace(',','.')
 try:return float(s)
 except:return float('nan')
for fid,cfg in cal.items():
 df,sep=load(fid); tc=df.columns[0]; vc=cfg['calibration_data']['value_column_name']
 ts=pd.Series(pd.NaT,index=df.index,dtype='datetime64[ns]')
 for fmt in ('%Y-%m-%d %H:%M:%S','%d.%m.%Y %H:%M:%S'):
  x=pd.to_datetime(df[tc],format=fmt,errors='coerce'); ts=ts.fillna(x)
 temp=df['inverter_temperature_C'].map(lambda s:num(s,sep)); val=df[vc].map(lambda s:num(s,sep))
 dupmask=ts.notna() & ts.duplicated(keep=False)
 spikes=ts[(ts.notna()) & (temp>85)]
 print('\n',fid,'valid=',ts.notna().sum(),'uniq=',ts.nunique(),'actual_dups=',dupmask.sum(),'spikes=',[(str(t),temp[i]) for i,t in spikes.items()])
 if dupmask.any():
  for i in df.index[dupmask]: print(' DUP idx',i,'ts',repr(df.at[i,tc]),'parsed',ts[i],'temp',df.at[i,'inverter_temperature_C'],'val',df.at[i,vc], 'forecast',df.at[i,'forecast_yield'])
 bad=ts.isna()
 for i in df.index[bad]: print(' BAD idx',i,'ts',repr(df.at[i,tc]),'temp',repr(df.at[i,'inverter_temperature_C']),'val',repr(df.at[i,vc]))
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:30000}); text(r.output)

